import{_ as o,o as l,c as a,a2 as i}from"./chunks/framework.CTeY_0bQ.js";const k=JSON.parse('{"title":"0005 入口 skill 命名","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0005-skill-names.md","filePath":"reference/adr/0005-skill-names.md","lastUpdated":null}'),d={name:"reference/adr/0005-skill-names.md"};function s(c,e,r,t,n,h){return l(),a("div",null,[...e[0]||(e[0]=[i('<div><h1 id="_0005-入口-skill-命名" tabindex="-1">0005 入口 skill 命名 <a class="header-anchor" href="#_0005-入口-skill-命名" aria-label="Permalink to &quot;0005 入口 skill 命名&quot;">​</a></h1><ul><li>状态：已采纳（2026-10-21，由项目负责人确认）</li><li>详见：<a href="https://github.com/yiyisf/laoshi/blob/main/docs/design/compat-migration.md" target="_blank" rel="noreferrer">compat-migration.md §2</a></li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>req-kit 的入口 skill 是 <code>/req</code>、<code>/req-setup</code>、<code>/req-doctor</code>、<code>/req-retro</code>，同事已经习惯。laoshi 是新的名字，团队内部也习惯称&quot;老师&quot;。保留旧名会让产品名和命令不一致；直接改名有学习成本。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li>laoshi 的入口 skill 命名为 <code>/laoshi</code>、<code>/laoshi-setup</code>、<code>/laoshi-doctor</code>、<code>/laoshi-retro</code>。</li><li><code>paseo-req-kit</code> 2.0 额外安装 <code>/req*</code> 转发 skill，只做命令转发并提示新名字，<strong>不复制手册内容</strong>。</li><li>命令行 <code>laoshi</code> 为主命令，<code>req</code>、<code>req-kit</code>、<code>paseo-req-kit</code>、<code>start-pipeline</code> 保留为别名。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>旧用户升级到 2.0 后 <code>/req</code> 仍可用，可以逐步改用 <code>/laoshi</code>。</li><li>转发 skill 在 laoshi 1.x 的整个生命周期内保留，何时移除另行决定。</li><li>文档、站点和汇报材料中的命令示例在 2.0 之后统一改为 <code>/laoshi*</code>。</li></ul><h2 id="实现-laoshi-m2e-2026-11-02" tabindex="-1">实现（laoshi M2e，2026-11-02） <a class="header-anchor" href="#实现-laoshi-m2e-2026-11-02" aria-label="Permalink to &quot;实现（laoshi M2e，2026-11-02）&quot;">​</a></h2><ul><li><code>skills/req*</code> 改名为 <code>skills/laoshi</code>、<code>laoshi-setup</code>、<code>laoshi-doctor</code>、<code>laoshi-retro</code>，frontmatter 的 <code>name</code> 同步；skill、提示词、引擎消息、契约中的 <code>/req*</code> 改为 <code>/laoshi*</code>。命令行 <code>req</code> 仍然可用（别名）。</li><li>skill 文案不写平台名：平台的说法用 <code>{{platform.&lt;词&gt;}}</code>，平台自己的一节（例如 <code>/laoshi-setup</code> 中工作区设置怎么写）用 <code>{{fragment.&lt;名称&gt;}}</code>，由 <code>engine/src/skills-render.ts</code> 在安装时按平台渲染（Paseo 的片段在 <code>adapters/paseo/skill/setup.md</code>，laoshi 内置能力的片段在 <code>engine/skill-fragments/setup-builtin.md</code>）。</li><li>转发用的 <code>/req*</code> 薄 skill 属于 paseo-req-kit 2.0（M7），这里没有。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/laoshi/blob/main/docs/adr/0005-skill-names.md">docs/adr/0005-skill-names.md</a> 生成。<a href="https://github.com/yiyisf/laoshi/edit/main/docs/adr/0005-skill-names.md">在 GitHub 上编辑</a></p>',2)])])}const u=o(d,[["render",s]]);export{k as __pageData,u as default};
